export function factoryPartCount(item,options={},catalog){
  if(!item)return 0;
  const weapon=catalog?.items[options.weaponId];
  const parts=weapon?.factoryParts??legacyFactoryParts[options.weaponId];
  const count=parts?.[item.id];
  return Number.isInteger(count)&&count>0?count:0;
}
export const isIncludedFactoryPart=(item,options,catalog)=>factoryPartCount(item,options,catalog)>0;
